const IDRANTE_SUBTYPES = ['UNI 45', 'UNI 70', 'Naspo'];
const PORTA_REI_SUBTYPES = ['Porta REI', 'Portone REI'];
const migrateExt = (e) => {
  if (e.category === 'Idrante UNI 45') return { ...e, category: 'Idrante', hydrantSubtype: 'UNI 45' };
  if (e.category === 'Idrante UNI 70') return { ...e, category: 'Idrante', hydrantSubtype: 'UNI 70' };
  if (e.category === 'Naspo')          return { ...e, category: 'Idrante', hydrantSubtype: 'Naspo' };
  return e;
};

