// ─── DASHBOARD ────────────────────────────────────────────────────────────────
function Dashboard({ activeProjectId, showToast }) {
  const [extinguishers, setExtinguishers] = useState([]);
  const [selectedExt, setSelectedExt] = useState(null);
  const [floorPlan, setFloorPlan] = useState('');
  const [addMode, setAddMode] = useState(false);
  const [newExt, setNewExt] = useState(null);
  const [checkModal, setCheckModal] = useState(null); // { ext, dueDate }
  const [issueModal, setIssueModal] = useState(null); // { ext, note }
  const [editExt, setEditExt] = useState(null);
  const planRef = useRef(null);
  const [zoomLevel, setZoomLevel] = useState(1);
  const [panX, setPanX] = useState(0);
  const [panY, setPanY] = useState(0);
  const [isPanning, setIsPanning] = useState(false);
  const lastPanPos = useRef({ x: 0, y: 0 });
  const initialTouchDistance = useRef(null);

  useEffect(() => { loadData(); setZoomLevel(1); setPanX(0); setPanY(0); }, [activeProjectId]);

  const loadData = () => {
    let data = getProjectData(activeProjectId, 'extinguishers') || [];
    data = data.map(e => migrateExt({ ...e, hasIssue: e.hasIssue ?? false }));
    setExtinguishers(data);
    setFloorPlan(getProjectData(activeProjectId, 'floorplan') || DEFAULT_FLOORPLAN);
  };
  const saveExtinguishers = (upd) => { saveProjectData(activeProjectId, 'extinguishers', upd); loadData(); };
  const saveRecord = (r) => {
    const recs = getProjectData(activeProjectId, 'records') || [];
    recs.push(r);
    saveProjectData(activeProjectId, 'records', recs);
  };
  const filterRecords = (num) => {
    const recs = (getProjectData(activeProjectId, 'records') || []).filter(r => r.extNumber !== num);
    saveProjectData(activeProjectId, 'records', recs);
  };

  const clampPan = (nx, ny, zoom) => {
    if (!planRef.current) return { x: 0, y: 0 };
    const { width, height } = planRef.current.getBoundingClientRect();
    const maxX = Math.max(0, width * (zoom - 1));
    const maxY = Math.max(0, height * (zoom - 1));
    return { x: Math.max(-maxX, Math.min(0, nx)), y: Math.max(-maxY, Math.min(0, ny)) };
  };

  const handleWheel = (e) => {
    e.preventDefault();
    if (addMode) return;
    let nz = zoomLevel + (e.deltaY < 0 ? 0.1 : -0.1);
    nz = Math.max(1, Math.min(5, nz));
    if (nz === zoomLevel) return;
    const rect = planRef.current.getBoundingClientRect();
    const cx = e.clientX - rect.left, cy = e.clientY - rect.top;
    const sf = nz / zoomLevel;
    const cp = clampPan(panX + (cx - (cx - panX) * sf), panY + (cy - (cy - panY) * sf), nz);
    setZoomLevel(nz); setPanX(cp.x); setPanY(cp.y);
  };
  const handleMouseDown = (e) => {
    if (addMode || zoomLevel === 1 || e.button !== 0) return;
    e.preventDefault(); setIsPanning(true); lastPanPos.current = { x: e.clientX, y: e.clientY };
  };
  const handleMouseMove = (e) => {
    if (!isPanning) return;
    const cp = clampPan(panX + e.clientX - lastPanPos.current.x, panY + e.clientY - lastPanPos.current.y, zoomLevel);
    setPanX(cp.x); setPanY(cp.y);
    lastPanPos.current = { x: e.clientX, y: e.clientY };
  };
  const handleMouseUp = () => setIsPanning(false);

  const getDistance = (t) => Math.hypot(t[0].clientX - t[1].clientX, t[0].clientY - t[1].clientY);
  const handleTouchStart = (e) => {
    if (addMode) return;
    if (e.touches.length === 1) { e.preventDefault(); setIsPanning(true); lastPanPos.current = { x: e.touches[0].clientX, y: e.touches[0].clientY }; }
    else if (e.touches.length === 2) { e.preventDefault(); setIsPanning(false); initialTouchDistance.current = getDistance(e.touches); }
  };
  const handleTouchMove = (e) => {
    if (addMode) return;
    if (e.touches.length === 2 && initialTouchDistance.current) {
      const curr = getDistance(e.touches);
      let nz = Math.max(1, Math.min(5, zoomLevel * (curr / initialTouchDistance.current)));
      if (nz === zoomLevel) return;
      const rect = planRef.current.getBoundingClientRect();
      const cx = (e.touches[0].clientX + e.touches[1].clientX) / 2 - rect.left;
      const cy = (e.touches[0].clientY + e.touches[1].clientY) / 2 - rect.top;
      const sf = nz / zoomLevel;
      const cp = clampPan(panX + (cx - (cx - panX) * sf), panY + (cy - (cy - panY) * sf), nz);
      setZoomLevel(nz); setPanX(cp.x); setPanY(cp.y);
      initialTouchDistance.current = curr;
    } else if (e.touches.length === 1 && isPanning && zoomLevel > 1) {
      e.preventDefault();
      const cp = clampPan(panX + e.touches[0].clientX - lastPanPos.current.x, panY + e.touches[0].clientY - lastPanPos.current.y, zoomLevel);
      setPanX(cp.x); setPanY(cp.y);
      lastPanPos.current = { x: e.touches[0].clientX, y: e.touches[0].clientY };
    }
  };
  const handleTouchEnd = () => { setIsPanning(false); initialTouchDistance.current = null; };

  const handleMarkerClick = (ext, e) => {
    e.stopPropagation();
    if (addMode || isPanning) return;
    setSelectedExt(ext);
  };

  const handlePlanClick = (e) => {
    if (!addMode) return;
    const rect = planRef.current.getBoundingClientRect();
    const cx = e.clientX - rect.left, cy = e.clientY - rect.top;
    const x = ((cx - panX) / zoomLevel / rect.width * 100);
    const y = ((cy - panY) / zoomLevel / rect.height * 100);
    if (x < 0 || x > 100 || y < 0 || y > 100) { showToast('Posizione fuori dalla planimetria', 'warning'); return; }
    const nd = new Date(); nd.setMonth(nd.getMonth() + 1);
    setNewExt({ id: Date.now().toString(), number: String(extinguishers.length + 1).padStart(3, '0'), category: 'Estintore', type: 'CO2', hydrantSubtype: '', portaReiSubtype: 'Porta REI', rei: '', battenti: '', costruttore: '', anno: '', matricola: '', potenzaEstinguente: '', capacita: '', capacitaUnit: 'Kg', scadenzaRevisione: '', scadenzaCollaudo: '', lunghezza: '', location: '', position: { x: x.toFixed(2), y: y.toFixed(2) }, maintenanceDue: nd.toISOString().split('T')[0], lastCheck: null, hasIssue: false });
    setAddMode(false);
  };

  const handleSaveNewExt = () => {
    if (!newExt.location.trim()) { showToast('Inserisci l\'ubicazione', 'warning'); return; }
    saveExtinguishers([...extinguishers, newExt]);
    setNewExt(null);
    showToast(`${newExt.category || 'Dispositivo'} ${newExt.number} aggiunto`, 'success');
  };

  const handleMarkControlled = () => {
    const nd = new Date(); nd.setMonth(nd.getMonth() + 6);
    setCheckModal({ ext: selectedExt, dueDate: nd.toISOString().split('T')[0] });
  };

  const handleConfirmCheck = () => {
    if (!checkModal.dueDate) { showToast('Seleziona la data di scadenza', 'warning'); return; }
    const now = new Date().toISOString();
    saveExtinguishers(extinguishers.map(x => x.id === checkModal.ext.id ? { ...x, lastCheck: now, maintenanceDue: checkModal.dueDate, hasIssue: false } : x));
    saveRecord({ id: Date.now().toString(), extNumber: checkModal.ext.number, timestamp: now, operator: JSON.parse(localStorage.getItem('firecheck_user'))?.email || 'Operatore' });
    setSelectedExt(null);
    setCheckModal(null);
    showToast(`✓ Controllo registrato — ${checkModal.ext.category || 'Elemento'} ${checkModal.ext.number}`, 'success');
  };

  const handleToggleIssue = (ext) => {
    if (ext.hasIssue) {
      saveExtinguishers(extinguishers.map(x => x.id === ext.id ? { ...x, hasIssue: false, issueNote: '' } : x));
      setSelectedExt(null);
      showToast(`Problema risolto — ${ext.category || 'Elemento'} ${ext.number}`, 'success');
    } else {
      setIssueModal({ ext, note: '' });
    }
  };

  const handleConfirmIssue = () => {
    saveExtinguishers(extinguishers.map(x => x.id === issueModal.ext.id ? { ...x, hasIssue: true, issueNote: issueModal.note.trim() } : x));
    setSelectedExt(null);
    setIssueModal(null);
    showToast(`Problema segnalato — ${issueModal.ext.category || 'Elemento'} ${issueModal.ext.number}`, 'warning');
  };

  const handleCancelCheck = () => {
    saveExtinguishers(extinguishers.map(x => x.id === selectedExt.id ? { ...x, lastCheck: null } : x));
    filterRecords(selectedExt.number);
    setSelectedExt(null);
    showToast('Controllo annullato', 'warning');
  };

  const handleEditExt = (ext) => { setEditExt({ ...ext }); setSelectedExt(null); };

  const handleSaveExt = () => {
    saveExtinguishers(extinguishers.map(e => e.id === editExt.id ? editExt : e));
    setEditExt(null);
    showToast('Modifiche salvate', 'success');
  };

  const handleDeleteExt = (ext) => {
    if (!confirm('Eliminare questo elemento?')) return;
    saveExtinguishers(extinguishers.filter(e => e.id !== ext.id));
    setSelectedExt(null);
    showToast('Elemento eliminato', 'warning');
  };

  const resetZoomPan = () => { setZoomLevel(1); setPanX(0); setPanY(0); };

  const total = extinguishers.length;
  const expired = extinguishers.filter(e => new Date(e.maintenanceDue) < new Date()).length;
  const issues = extinguishers.filter(e => e.hasIssue).length;
  const ok = total - expired - issues;

  return (
    <div>
      {/* STAT CARDS */}
      <div className="stats-grid">
        <div className="stat-card stat-total"><div className="stat-value">{total}</div><div className="stat-label">Totale Dispositivi</div></div>
        <div className="stat-card stat-ok"><div className="stat-value">{ok < 0 ? 0 : ok}</div><div className="stat-label">Operativi</div></div>
        <div className="stat-card stat-expired"><div className="stat-value">{expired}</div><div className="stat-label">Scaduti</div></div>
        <div className="stat-card stat-issue"><div className="stat-value">{issues}</div><div className="stat-label">Con Problemi</div></div>
      </div>

      {/* FLOOR PLAN CARD */}
      <div className="card">
        <div className="flex-between gap-md" style={{ marginBottom: '0.75rem' }}>
          <div className="card-title" style={{ marginBottom: 0 }}><span className="ct-icon">◎</span> Planimetria</div>
          <div className="flex gap-sm">
            {zoomLevel > 1 && <button className="btn btn-ghost btn-sm" onClick={resetZoomPan}>Reset zoom</button>}
            <button className={`btn btn-sm ${addMode ? 'btn-danger' : 'btn-success'}`} onClick={() => setAddMode(!addMode)}>
              {addMode ? '✕ Annulla' : '+ Aggiungi Dispositivo'}
            </button>
          </div>
        </div>

        {addMode && <div className="addmode-banner">◉ Clicca sulla planimetria per posizionare il nuovo dispositivo</div>}

        <div className="legend" style={{ flexWrap: 'wrap' }}>
          {EQUIPMENT_CATEGORIES.map(c => (
            <div key={c.id} className="legend-item"><div className="legend-dot" style={{ background: c.color }}></div>{c.icon} {c.label}</div>
          ))}
          <div className="legend-item"><div className="legend-dot" style={{ background: 'var(--red)' }}></div>Scaduto</div>
          <div className="legend-item"><div className="legend-dot" style={{ background: 'var(--yellow)' }}></div>Problema</div>
          {zoomLevel > 1 && <div className="legend-item" style={{ marginLeft: 'auto' }}><span className="zoom-badge">Zoom {zoomLevel.toFixed(1)}×</span></div>}
        </div>

        <div
          ref={planRef}
          className="floor-plan"
          style={{ cursor: addMode ? 'crosshair' : (isPanning ? 'grabbing' : (zoomLevel > 1 ? 'grab' : 'default')) }}
          onWheel={handleWheel}
          onMouseDown={handleMouseDown} onMouseMove={handleMouseMove} onMouseUp={handleMouseUp} onMouseLeave={handleMouseUp}
          onClick={handlePlanClick}
          onTouchStart={handleTouchStart} onTouchMove={handleTouchMove} onTouchEnd={handleTouchEnd} onTouchCancel={handleTouchEnd}
        >
          <div className="floor-plan-content" style={{ transform: `translate(${panX}px,${panY}px) scale(${zoomLevel})`, transformOrigin: '0 0', transition: isPanning ? 'none' : 'transform 0.1s ease-out' }} onClick={e => isPanning && e.stopPropagation()}>
            {floorPlan && <img src={floorPlan} alt="Planimetria" />}
            {extinguishers.map(ext => {
              const isOverdue = new Date(ext.maintenanceDue) < new Date();
              const cat = EQUIPMENT_CATEGORIES.find(c => c.id === (ext.category || 'Estintore')) || EQUIPMENT_CATEGORIES[0];
              const markerCls = ext.hasIssue ? 'marker marker-yellow' : isOverdue ? 'marker marker-red' : 'marker';
              const okBg = (!ext.hasIssue && !isOverdue) ? { background: cat.color } : {};
              return (
                <div key={ext.id} className={markerCls} style={{ left: `${ext.position.x}%`, top: `${ext.position.y}%`, ...okBg }}
                  onClick={e => handleMarkerClick(ext, e)}
                  title={`${cat.icon} ${ext.number} — ${ext.category === 'Idrante' && ext.hydrantSubtype ? 'Idrante ' + ext.hydrantSubtype + ' · ' : ''}${ext.category === 'Porta REI' && ext.portaReiSubtype ? ext.portaReiSubtype + ' · ' : ''}${ext.location}${ext.hasIssue ? ' ⚠ PROBLEMA' : ''}`}>
                  {ext.number}
                </div>
              );
            })}
          </div>
        </div>
      </div>

      {/* SELECTED EXT MODAL */}
      {selectedExt && (() => {
        const selCat = EQUIPMENT_CATEGORIES.find(c => c.id === (selectedExt.category || 'Estintore')) || EQUIPMENT_CATEGORIES[0];
        return (
          <div className="modal" onClick={() => setSelectedExt(null)}>
            <div className="modal-box" onClick={e => e.stopPropagation()}>
              <div className="modal-title">
                {selCat.icon} {selectedExt.category === 'Porta REI' ? (selectedExt.portaReiSubtype || 'Porta REI') : (selCat.label + (selectedExt.hydrantSubtype ? ' ' + selectedExt.hydrantSubtype : ''))} <span className="font-mono">{selectedExt.number}</span>
                {selectedExt.hasIssue && <span className="badge badge-issue" style={{ marginLeft: 'auto' }}>⚠ Problema</span>}
                {!selectedExt.hasIssue && new Date(selectedExt.maintenanceDue) < new Date() && <span className="badge badge-expired" style={{ marginLeft: 'auto' }}>Scaduto</span>}
                {!selectedExt.hasIssue && new Date(selectedExt.maintenanceDue) >= new Date() && <span className="badge badge-ok" style={{ marginLeft: 'auto' }}>OK</span>}
                <button className="btn btn-ghost btn-sm" style={{ padding: '0.3rem 0.5rem' }} title="Modifica" onClick={() => handleEditExt(selectedExt)}>✏</button>
                <button className="btn btn-ghost btn-sm" style={{ padding: '0.3rem 0.5rem', color: 'var(--red)' }} title="Elimina" onClick={() => handleDeleteExt(selectedExt)}>🗑</button>
              </div>
              <hr className="modal-divider" />
              <div className="modal-field"><span className="label">Categoria</span><span className="modal-value">{selectedExt.category === 'Porta REI' ? (selectedExt.portaReiSubtype || 'Porta REI') : (selCat.label + (selectedExt.hydrantSubtype ? ' ' + selectedExt.hydrantSubtype : ''))}</span></div>
              {selectedExt.category === 'Porta REI' && (selectedExt.costruttore || selectedExt.anno || selectedExt.matricola || selectedExt.rei) && (
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0 0.75rem' }}>
                  {selectedExt.costruttore && <div className="modal-field" style={{ gridColumn: '1 / -1' }}><span className="label">Costruttore</span><span className="modal-value">{selectedExt.costruttore}</span></div>}
                  {selectedExt.anno && <div className="modal-field"><span className="label">Anno</span><span className="modal-value mono">{selectedExt.anno}</span></div>}
                  {selectedExt.matricola && <div className="modal-field"><span className="label">Matricola</span><span className="modal-value mono">{selectedExt.matricola}</span></div>}
                  {selectedExt.rei && <div className="modal-field"><span className="label">REI</span><span className="modal-value mono">{selectedExt.rei}</span></div>}
                  {selectedExt.battenti && <div className="modal-field"><span className="label">Battenti</span><span className="modal-value mono">{selectedExt.battenti}</span></div>}
                </div>
              )}
              {selectedExt.category === 'Idrante' && (selectedExt.costruttore || selectedExt.anno || selectedExt.lunghezza) && (
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0 0.75rem' }}>
                  {selectedExt.costruttore && <div className="modal-field" style={{ gridColumn: '1 / -1' }}><span className="label">Costruttore</span><span className="modal-value">{selectedExt.costruttore}</span></div>}
                  {selectedExt.anno && <div className="modal-field"><span className="label">Anno</span><span className="modal-value mono">{selectedExt.anno}</span></div>}
                  {selectedExt.lunghezza && <div className="modal-field"><span className="label">Lunghezza</span><span className="modal-value mono">{selectedExt.lunghezza} m</span></div>}
                </div>
              )}
              {(selectedExt.category === 'Estintore' || !selectedExt.category) && <>
                <div className="modal-field"><span className="label">Tipo Agente</span><span className="modal-value">{selectedExt.type}</span></div>
                {selectedExt.costruttore && <div className="modal-field"><span className="label">Costruttore</span><span className="modal-value">{selectedExt.costruttore}</span></div>}
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0 0.75rem' }}>
                  {selectedExt.anno && <div className="modal-field"><span className="label">Anno</span><span className="modal-value mono">{selectedExt.anno}</span></div>}
                  {selectedExt.matricola && <div className="modal-field"><span className="label">Matricola</span><span className="modal-value mono">{selectedExt.matricola}</span></div>}
                  {selectedExt.potenzaEstinguente && <div className="modal-field"><span className="label">Potenza</span><span className="modal-value mono">{selectedExt.potenzaEstinguente}</span></div>}
                  {selectedExt.capacita && <div className="modal-field"><span className="label">Capacità</span><span className="modal-value mono">{selectedExt.capacita} {selectedExt.capacitaUnit || 'Kg'}</span></div>}
                  {selectedExt.scadenzaRevisione && <div className="modal-field"><span className="label">Sc. Revisione</span><span className="modal-value mono" style={{ color: parseInt(selectedExt.scadenzaRevisione) < new Date().getFullYear() ? 'var(--red)' : 'inherit' }}>{selectedExt.scadenzaRevisione}</span></div>}
                  {selectedExt.scadenzaCollaudo && <div className="modal-field"><span className="label">Sc. Collaudo</span><span className="modal-value mono" style={{ color: parseInt(selectedExt.scadenzaCollaudo) < new Date().getFullYear() ? 'var(--red)' : 'inherit' }}>{selectedExt.scadenzaCollaudo}</span></div>}
                </div>
              </>}
              <div className="modal-field"><span className="label">Ubicazione</span><span className="modal-value">{selectedExt.location}</span></div>
              <div className="modal-field"><span className="label">Scadenza Manutenzione</span><span className="modal-value mono">{new Date(selectedExt.maintenanceDue).toLocaleDateString('it-IT')}</span></div>
              <div className="modal-field"><span className="label">Ultimo Controllo</span><span className="modal-value mono">{selectedExt.lastCheck ? new Date(selectedExt.lastCheck).toLocaleString('it-IT') : '— nessuno'}</span></div>
              {selectedExt.hasIssue && selectedExt.issueNote && (
                <div className="modal-field"><span className="label">Note problema</span><span className="modal-value" style={{ color: 'var(--yellow)', whiteSpace: 'pre-wrap' }}>{selectedExt.issueNote}</span></div>
              )}
              <hr className="modal-divider" />
              <div className="flex gap-sm" style={{ flexWrap: 'wrap' }}>
                <button className="btn btn-success" style={{ flex: 1 }} onClick={handleMarkControlled}>✓ Segna Controllato</button>
                <button className="btn btn-warning" style={{ flex: 1 }} onClick={() => handleToggleIssue(selectedExt)}>
                  {selectedExt.hasIssue ? '✓ Risolvi Problema' : '⚠ Segnala Problema'}
                </button>
                {selectedExt.lastCheck && (
                  <button className="btn btn-danger" style={{ flex: 1 }} onClick={handleCancelCheck}>✕ Annulla Controllo</button>
                )}
                <button className="btn btn-ghost" style={{ flex: 1 }} onClick={() => setSelectedExt(null)}>Chiudi</button>
              </div>
            </div>
          </div>
        );
      })()}

      {/* CHECK MODAL — SCADENZA */}
      {checkModal && (
        <div className="modal" onClick={() => setCheckModal(null)}>
          <div className="modal-box" onClick={e => e.stopPropagation()}>
            <div className="modal-title">📅 Imposta Scadenza — Estintore <span className="font-mono">{checkModal.ext.number}</span></div>
            <hr className="modal-divider" />
            <label className="label">Data di Scadenza *</label>
            <input
              className="input"
              type="date"
              value={checkModal.dueDate}
              onChange={e => setCheckModal({ ...checkModal, dueDate: e.target.value })}
              autoFocus
            />
            <button
              className="btn btn-secondary w-full"
              style={{ marginBottom: '1rem', justifyContent: 'center' }}
              onClick={() => {
                const nd = new Date(); nd.setMonth(nd.getMonth() + 6);
                setCheckModal({ ...checkModal, dueDate: nd.toISOString().split('T')[0] });
              }}
            >
              ⟳ Imposta automaticamente a +6 mesi
            </button>
            <div className="flex gap-sm">
              <button className="btn btn-success" style={{ flex: 1 }} onClick={handleConfirmCheck}>✓ Conferma Controllo</button>
              <button className="btn btn-ghost" style={{ flex: 1 }} onClick={() => setCheckModal(null)}>Annulla</button>
            </div>
          </div>
        </div>
      )}

      {/* ISSUE MODAL */}
      {issueModal && (
        <div className="modal" onClick={() => setIssueModal(null)}>
          <div className="modal-box" onClick={e => e.stopPropagation()}>
            <div className="modal-title">⚠ Segnala Problema — <span className="font-mono">{issueModal.ext.number}</span></div>
            <hr className="modal-divider" />
            <label className="label">Descrizione del problema</label>
            <textarea
              className="input"
              rows={4}
              style={{ resize: 'vertical', fontFamily: 'var(--font-body)', height: 'auto' }}
              placeholder="Descrivi il problema riscontrato…"
              value={issueModal.note}
              onChange={e => setIssueModal({ ...issueModal, note: e.target.value })}
              autoFocus
            />
            <div className="flex gap-sm" style={{ marginTop: '0.25rem' }}>
              <button className="btn btn-warning" style={{ flex: 1, justifyContent: 'center' }} onClick={handleConfirmIssue}>⚠ Conferma Problema</button>
              <button className="btn btn-ghost" style={{ flex: 1, justifyContent: 'center' }} onClick={() => setIssueModal(null)}>Annulla</button>
            </div>
          </div>
        </div>
      )}

      {/* NEW EXT MODAL */}
      {newExt && (
        <div className="modal" onClick={() => setNewExt(null)}>
          <div className="modal-box" onClick={e => e.stopPropagation()}>
            <div className="modal-title">+ Nuovo Dispositivo</div>
            <label className="label">Categoria</label>
            <select className="select" value={newExt.category || 'Estintore'} onChange={e => setNewExt({ ...newExt, category: e.target.value, type: e.target.value === 'Estintore' ? 'CO2' : '', hydrantSubtype: e.target.value === 'Idrante' ? 'UNI 45' : '', portaReiSubtype: e.target.value === 'Porta REI' ? 'Porta REI' : '' })}>
              {EQUIPMENT_CATEGORIES.map(c => <option key={c.id} value={c.id}>{c.icon} {c.label}</option>)}
            </select>
            {newExt.category === 'Idrante' && (
              <>
                <label className="label">Tipo Idrante</label>
                <select className="select" value={newExt.hydrantSubtype || 'UNI 45'} onChange={e => setNewExt({ ...newExt, hydrantSubtype: e.target.value })}>
                  {IDRANTE_SUBTYPES.map(t => <option key={t}>{t}</option>)}
                </select>
                <label className="label">Costruttore</label>
                <input className="input" value={newExt.costruttore || ''} onChange={e => setNewExt({ ...newExt, costruttore: e.target.value })} placeholder="es. Soval" />
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0 0.75rem' }}>
                  <div>
                    <label className="label">Anno</label>
                    <input className="input" type="number" min="2000" max="2099" placeholder="es. 2020" value={newExt.anno || ''} onChange={e => setNewExt({ ...newExt, anno: e.target.value })} />
                  </div>
                  <div>
                    <label className="label">Lunghezza (m)</label>
                    <input className="input" type="number" min="0" step="0.5" placeholder="es. 20" value={newExt.lunghezza || ''} onChange={e => setNewExt({ ...newExt, lunghezza: e.target.value })} />
                  </div>
                </div>
              </>
            )}
            {newExt.category === 'Porta REI' && (
              <>
                <label className="label">Tipo</label>
                <select className="select" value={newExt.portaReiSubtype || 'Porta REI'} onChange={e => setNewExt({ ...newExt, portaReiSubtype: e.target.value })}>
                  {PORTA_REI_SUBTYPES.map(t => <option key={t}>{t}</option>)}
                </select>
                <label className="label">Costruttore</label>
                <input className="input" value={newExt.costruttore || ''} onChange={e => setNewExt({ ...newExt, costruttore: e.target.value })} placeholder="es. Dierre" />
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0 0.75rem' }}>
                  <div>
                    <label className="label">Anno</label>
                    <input className="input" type="number" min="2000" max="2099" placeholder="es. 2021" value={newExt.anno || ''} onChange={e => setNewExt({ ...newExt, anno: e.target.value })} />
                  </div>
                  <div>
                    <label className="label">Matricola</label>
                    <input className="input" value={newExt.matricola || ''} onChange={e => setNewExt({ ...newExt, matricola: e.target.value })} placeholder="es. AB123456" />
                  </div>
                  <div>
                    <label className="label">REI</label>
                    <select className="select" value={newExt.rei || ''} onChange={e => setNewExt({ ...newExt, rei: e.target.value })}>
                      <option value="">— seleziona —</option>
                      {['REI 15','REI 30','REI 45','REI 60','REI 90','REI 120','REI 180','REI 240'].map(r => <option key={r}>{r}</option>)}
                    </select>
                  </div>
                  <div>
                    <label className="label">N° Battenti</label>
                    <select className="select" value={newExt.battenti || ''} onChange={e => setNewExt({ ...newExt, battenti: e.target.value })}>
                      <option value="">— seleziona —</option>
                      <option value="1">1 battente</option>
                      <option value="2">2 battenti</option>
                    </select>
                  </div>
                </div>
              </>
            )}
            <label className="label">Numero / Codice</label>
            <input className="input" value={newExt.number} onChange={e => setNewExt({ ...newExt, number: e.target.value })} placeholder="001" />
            {(newExt.category === 'Estintore' || !newExt.category) && (
              <>
                <label className="label">Tipo Agente Estinguente</label>
                <select className="select" value={newExt.type} onChange={e => setNewExt({ ...newExt, type: e.target.value })}>
                  {['CO2','Polvere','Schiuma','Acqua','Idrico','Classe K'].map(t => <option key={t}>{t}</option>)}
                </select>
                <label className="label">Costruttore</label>
                <input className="input" value={newExt.costruttore || ''} onChange={e => setNewExt({ ...newExt, costruttore: e.target.value })} placeholder="es. Amerex" />
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0 0.75rem' }}>
                  <div>
                    <label className="label">Anno</label>
                    <input className="input" value={newExt.anno || ''} onChange={e => setNewExt({ ...newExt, anno: e.target.value })} placeholder="es. 2020" maxLength={4} />
                  </div>
                  <div>
                    <label className="label">Matricola</label>
                    <input className="input" value={newExt.matricola || ''} onChange={e => setNewExt({ ...newExt, matricola: e.target.value })} placeholder="es. AB123456" />
                  </div>
                  <div>
                    <label className="label">Potenza Estinguente</label>
                    <input className="input" value={newExt.potenzaEstinguente || ''} onChange={e => setNewExt({ ...newExt, potenzaEstinguente: e.target.value })} placeholder="es. 21A 113B C" />
                  </div>
                  <div>
                    <label className="label">Kg / L</label>
                    <div style={{ display: 'flex', gap: '0.4rem' }}>
                      <input className="input" style={{ marginBottom: 0, flex: 1 }} value={newExt.capacita || ''} onChange={e => setNewExt({ ...newExt, capacita: e.target.value })} placeholder="es. 6" />
                      <select className="select" style={{ marginBottom: 0, width: 70 }} value={newExt.capacitaUnit || 'Kg'} onChange={e => setNewExt({ ...newExt, capacitaUnit: e.target.value })}>
                        <option>Kg</option><option>L</option>
                      </select>
                    </div>
                  </div>
                </div>
              </>
            )}
            <label className="label">Ubicazione *</label>
            <input className="input" value={newExt.location} onChange={e => setNewExt({ ...newExt, location: e.target.value })} placeholder="es. Ingresso principale" autoFocus />
            <label className="label">Scadenza Manutenzione</label>
            <input className="input" type="date" value={newExt.maintenanceDue} onChange={e => setNewExt({ ...newExt, maintenanceDue: e.target.value })} />
            {(newExt.category === 'Estintore' || !newExt.category) && (
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0 0.75rem' }}>
                <div>
                  <label className="label">Scadenza Revisione</label>
                  <input className="input" type="number" min="2000" max="2099" placeholder="es. 2027" value={newExt.scadenzaRevisione || ''} onChange={e => setNewExt({ ...newExt, scadenzaRevisione: e.target.value })} />
                </div>
                <div>
                  <label className="label">Scadenza Collaudo</label>
                  <input className="input" type="number" min="2000" max="2099" placeholder="es. 2030" value={newExt.scadenzaCollaudo || ''} onChange={e => setNewExt({ ...newExt, scadenzaCollaudo: e.target.value })} />
                </div>
              </div>
            )}
            <div className="flex gap-sm" style={{ marginTop: '0.25rem' }}>
              <button className="btn btn-success" style={{ flex: 1 }} onClick={handleSaveNewExt}>✓ Conferma</button>
              <button className="btn btn-ghost" style={{ flex: 1 }} onClick={() => setNewExt(null)}>Annulla</button>
            </div>
          </div>
        </div>
      )}

      <ExtEditModal editExt={editExt} setEditExt={setEditExt} onSave={handleSaveExt} onClose={() => setEditExt(null)} />
    </div>
  );
}

// ─── REPORT OPERATIONS ───────────────────────────────────────────────────────
const REPORT_OPS = [
  { id: 'reg',     label: 'Compilazione registro antincendio' },
  { id: 'ext_ord', label: 'Manutenzione ordinaria semestrale estintori' },
  { id: 'ext_str', label: 'Manutenzione straordinaria estintori' },
  { id: 'idr_ord', label: 'Manutenzione ordinaria semestrale idranti' },
  { id: 'idro',    label: 'Prova idrodinamica annuale, pressione rilevata', hasField: true, fieldPlaceholder: '___ bar' },
  { id: 'col',     label: 'Collaudo tubazioni rigide/semirigide' },
  { id: 'idr_str', label: 'Manutenzione straordinaria reti idranti rigide/semirigide' },
  { id: 'rev',     label: 'Revisioni programmate n°', hasField: true, fieldPlaceholder: '____' },
  { id: 'ext_tmp', label: 'Estintori temporanei n°', hasField: true, fieldPlaceholder: '____' },
];
const defaultOps = () => REPORT_OPS.map(o => ({ id: o.id, checked: false, fieldValue: '' }));

// ─── HISTORY ──────────────────────────────────────────────────────────────────
function History({ activeProjectId, showToast }) {
  const [records, setRecords] = useState([]);
  const [extinguishers, setExtinguishers] = useState([]);
  const [filterExt, setFilterExt] = useState('all');
  const [showReportModal, setShowReportModal] = useState(false);
  const [reportNotes, setReportNotes] = useState('');
  const [reportTechnician, setReportTechnician] = useState('');
  const [reportCompany, setReportCompany] = useState({ azienda: '', indirizzo: '', riferimento: '' });
  const [reportOps, setReportOps] = useState(defaultOps);
  const [reportOpType, setReportOpType] = useState('ordinaria');
  const [reportFloorPlan, setReportFloorPlan] = useState(null);

  useEffect(() => { loadData(); }, [activeProjectId]);

  const loadData = () => {
    const recs = (getProjectData(activeProjectId, 'records') || []).sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp));
    const exts = (getProjectData(activeProjectId, 'extinguishers') || []).map(migrateExt);
    const fp = getProjectData(activeProjectId, 'floorplan') || null;
    setRecords(recs);
    setExtinguishers(exts);
    setReportFloorPlan(fp && !fp.startsWith('data:image/svg') ? fp : null);
  };

  const getExtLocation = (num) => extinguishers.find(e => e.number === num)?.location || 'N/D';
  const isExtPositive = (num) => { const ext = extinguishers.find(e => e.number === num); return ext ? !ext.hasIssue : true; };
  const getItemCategory = (num) => { const ext = extinguishers.find(e => e.number === num); return (ext?.category) || 'Estintore'; };
  const getItemLabel = (num) => { const ext = extinguishers.find(e => e.number === num); if (!ext) return 'Estintore'; if (ext.category === 'Idrante' && ext.hydrantSubtype) return `Idrante ${ext.hydrantSubtype}`; return ext.category || 'Estintore'; };

  const todayStr = new Date().toISOString().split('T')[0];
  const todayRecords = records.filter(r => r.timestamp.startsWith(todayStr));

  const filtered = filterExt === 'all' ? records : records.filter(r => r.extNumber === filterExt);
  const usedNumbers = [...new Set(records.map(r => r.extNumber))].sort();

  const downloadCSV = () => {
    let csv = '\uFEFF' + 'N\u00b0;Tipo;Ubicazione;Data;Ora;Operatore;Esito\n';
    csv += filtered.map(r => {
      const d = new Date(r.timestamp);
      return [r.extNumber, getItemCategory(r.extNumber), getExtLocation(r.extNumber), d.toLocaleDateString('it-IT'), d.toLocaleTimeString('it-IT'), r.operator || '', isExtPositive(r.extNumber) ? 'Positivo' : 'Negativo'].map(c => `"${c}"`).join(';');
    }).join('\n');
    const a = document.createElement('a');
    a.href = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8;' }));
    a.download = `storico_controlli_${new Date().toISOString().split('T')[0]}.csv`;
    a.click();
  };

  const adaptLabel = (label) => {
    if (reportOpType === 'straordinaria') {
      return label.replace(/\bordinaria\b/g, 'straordinaria').replace(/\bordinarie\b/g, 'straordinarie');
    }
    return label.replace(/\bstraordinaria\b/g, 'ordinaria').replace(/\bstraordinarie\b/g, 'ordinarie');
  };

  const generateReport = async () => {
    if (todayRecords.length === 0) { showToast('Nessun controllo registrato oggi', 'warning'); return; }
    if (!window.jspdf) { showToast('Libreria PDF non disponibile', 'error'); return; }
    const { jsPDF } = window.jspdf;
    const doc = new jsPDF();
    const today = new Date();
    const controlled = todayRecords.length;

    // ── Raggruppa per categoria
    const categoryGroups = EQUIPMENT_CATEGORIES
      .filter(c => todayRecords.some(r => getItemCategory(r.extNumber) === c.id))
      .map(c => {
        const recs = todayRecords.filter(r => getItemCategory(r.extNumber) === c.id);
        const pos = recs.filter(r => isExtPositive(r.extNumber)).length;
        const neg = recs.length - pos;
        return { cat: c, recs, pos, neg };
      });

    // ── Logo in alto a destra
    try { doc.addImage(LOGO_B64, 'PNG', 176, 6, 20, 20); } catch(e) {}
    doc.setFontSize(8);
    doc.setTextColor(200, 200, 200);
    doc.setFont(undefined, 'normal');
    doc.text('FireCheck', 174, 30, { align: 'right' });

    // ── Blocco dati azienda
    const co = reportCompany;
    const lineH = 7;
    let ay = 16;
    const drawField = (label, value, x, y, w) => {
      doc.setFontSize(7.5);
      doc.setTextColor(130, 130, 130);
      doc.setFont(undefined, 'normal');
      doc.text(label, x, y);
      doc.setTextColor(30, 30, 30);
      doc.setFont(undefined, 'bold');
      const displayVal = value && value.trim() ? value.trim() : '';
      if (displayVal) {
        doc.text(displayVal, x, y + 4);
      } else {
        doc.setDrawColor(180, 180, 180);
        doc.setLineWidth(0.3);
        doc.line(x, y + 4.5, x + w, y + 4.5);
      }
    };
    const colW = 87;
    drawField('Azienda', co.azienda, 14, ay, colW);
    drawField('Riferimento interno', co.riferimento, 14 + colW + 6, ay, colW);
    ay += lineH + 3;
    drawField('Sede', co.indirizzo, 14, ay, colW * 2 + 6);
    ay += lineH + 3;

    doc.setDrawColor(255, 95, 31);
    doc.setLineWidth(0.4);
    doc.line(14, ay, 196, ay);
    ay += 7;

    // ── Titolo rapporto
    doc.setFontSize(13);
    doc.setTextColor(255, 95, 31);
    doc.setFont(undefined, 'bold');
    doc.text('Rapporto di Controllo Presidi Antincendio', 14, ay);
    ay += 6;
    doc.setFontSize(8.5);
    doc.setTextColor(100, 100, 100);
    doc.setFont(undefined, 'normal');
    doc.text(`Data: ${today.toLocaleDateString('it-IT', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}`, 14, ay);
    doc.text(`Generato: ${today.toLocaleString('it-IT')}`, 196, ay, { align: 'right' });
    ay += 9;

    // ── Paragrafo certificazione
    const techName = reportTechnician.trim() || '______________________';
    const dateIt = today.toLocaleDateString('it-IT');
    const certText = `Il giorno ${dateIt} il tecnico ${techName} ha effettuato il controllo semestrale dei presidi antincendio secondo la norma di riferimento UNI 9994-1:2013, UNI 10779:2014, UNI 11473-1 all’interno dei locali dell’azienda di cui all’intestazione.`;
    doc.setFontSize(9.5);
    doc.setTextColor(40, 40, 40);
    doc.setFont(undefined, 'italic');
    const certLines = doc.splitTextToSize(certText, 182);
    doc.text(certLines, 14, ay);
    ay += certLines.length * 5.5 + 8;

    doc.setDrawColor(220, 220, 220);
    doc.setLineWidth(0.3);
    doc.line(14, ay - 4, 196, ay - 4);

    // ── Tabella riepilogo (una riga per categoria)
    doc.autoTable({
      startY: ay,
      head: [['Tipo', 'Controllati', 'Positivi', 'Negativi']],
      body: categoryGroups.map(g => [g.cat.label, String(g.recs.length), String(g.pos), String(g.neg)]),
      headStyles: { fillColor: [255, 95, 31], textColor: 255, fontStyle: 'bold', fontSize: 9 },
      bodyStyles: { fontSize: 10, valign: 'middle' },
      columnStyles: {
        0: { cellWidth: 'auto' },
        1: { cellWidth: 30, halign: 'center' },
        2: { cellWidth: 28, halign: 'center' },
        3: { cellWidth: 28, halign: 'center' }
      },
      didParseCell: (data) => {
        if (data.section === 'body') {
          if (data.column.index === 2) data.cell.styles.textColor = [34, 160, 80];
          if (data.column.index === 3 && Number(data.cell.raw) > 0) data.cell.styles.textColor = [210, 60, 60];
        }
      },
      theme: 'grid',
      margin: { left: 14, right: 14 }
    });

    // ── Tabella Estintori (solo estintori)
    const extintoriList = extinguishers.filter(e => e.category === 'Estintore' || !e.category);
    if (extintoriList.length > 0) {
      let tableAy = doc.lastAutoTable.finalY + 10;
      const pageH = doc.internal.pageSize.height;
      if (tableAy > pageH - 50) { doc.addPage(); tableAy = 20; }
      
      doc.setFontSize(10);
      doc.setTextColor(60, 60, 60);
      doc.setFont(undefined, 'bold');
      doc.text('Tabella Estintori', 14, tableAy);
      tableAy += 7;

      const tableHead = [['N°', 'Agente', 'Costruttore', 'Anno', 'Matricola', 'Potenza', 'Kg/L', 'Ubicazione', 'Scad. Mant.', 'Esito']];
      let tableBody = [];
      extintoriList.forEach(ext => {
        const esito = ext.hasIssue ? 'Problema' : (new Date(ext.maintenanceDue) < new Date() ? 'Scaduto' : 'Positivo');
        tableBody.push([
          ext.number,
          ext.type || '',
          ext.costruttore || '',
          ext.anno || '',
          ext.matricola || '',
          ext.potenzaEstinguente || '',
          (ext.capacita ? ext.capacita + ' ' + (ext.capacitaUnit || 'Kg') : ''),
          ext.location || '',
          ext.maintenanceDue ? new Date(ext.maintenanceDue).toLocaleDateString('it-IT') : '',
          esito
        ]);
        // Se ha problema, aggiungi riga con nota
        if (ext.hasIssue && ext.issueNote) {
          tableBody.push([
            { content: 'NOTA:', styles: { fontStyle: 'bold', fillColor: [255, 245, 230] } },
            { content: ext.issueNote, colSpan: 9, styles: { fillColor: [255, 245, 230], textColor: [180, 90, 0] } }
          ]);
        }
      });

      doc.autoTable({
        startY: tableAy,
        head: tableHead,
        body: tableBody,
        headStyles: { fillColor: [255, 95, 31], textColor: 255, fontStyle: 'bold', fontSize: 8, halign: 'left', valign: 'middle' },
        bodyStyles: { fontSize: 7.5, valign: 'top' },
        columnStyles: {
          0: { cellWidth: 12, halign: 'center' },
          1: { cellWidth: 20 },
          2: { cellWidth: 20 },
          3: { cellWidth: 12, halign: 'center' },
          4: { cellWidth: 16 },
          5: { cellWidth: 16 },
          6: { cellWidth: 14 },
          7: { cellWidth: 38, halign: 'left' },
          8: { cellWidth: 16, halign: 'center' },
          9: { cellWidth: 16, halign: 'center' }
        },
        theme: 'grid',
        margin: { left: 14, right: 14 },
        didParseCell: (data) => {
          if (data.section === 'body') {
            const rowIndex = data.rowIndex;
            // Verifica se è una riga di nota (contiene colSpan)
            const isNoteRow = tableBody[rowIndex] && tableBody[rowIndex][0] && tableBody[rowIndex][0].colSpan;
            if (!isNoteRow) {
              const ext = extintoriList[rowIndex];
              if (ext && ext.hasIssue) {
                data.cell.styles.textColor = [210, 60, 60];
              }
              if (ext && new Date(ext.maintenanceDue) < new Date() && !ext.hasIssue) {
                data.cell.styles.textColor = [210, 60, 60];
              }
            }
          }
        }
      });
    }

    // ── Tabella Idranti
    const idrantiList = extinguishers.filter(e => e.category === 'Idrante');
    if (idrantiList.length > 0) {
      let tableAy = doc.lastAutoTable?.finalY ? doc.lastAutoTable.finalY + 10 : (doc.lastAutoTable?.finalY || 0) + 60;
      const pageH = doc.internal.pageSize.height;
      if (tableAy > pageH - 50) { doc.addPage(); tableAy = 20; }
      
      doc.setFontSize(10);
      doc.setTextColor(60, 60, 60);
      doc.setFont(undefined, 'bold');
      doc.text('Tabella Idranti', 14, tableAy);
      tableAy += 7;

      const tableHead = [['Categoria', 'Tipo', 'Costruttore', 'Anno', 'Lungh. (m)', 'N°', 'Ubicazione', 'Scad. Mant.', 'Esito']];
      let tableBody = [];
      idrantiList.forEach(idr => {
        const esito = idr.hasIssue ? 'Problema' : (new Date(idr.maintenanceDue) < new Date() ? 'Scaduto' : 'Positivo');
        tableBody.push([
          idr.category || 'Idrante',
          idr.hydrantSubtype || '',
          idr.costruttore || '',
          idr.anno || '',
          idr.lunghezza || '',
          idr.number,
          idr.location || '',
          idr.maintenanceDue ? new Date(idr.maintenanceDue).toLocaleDateString('it-IT') : '',
          esito
        ]);
        // Se ha problema, aggiungi riga con nota
        if (idr.hasIssue && idr.issueNote) {
          tableBody.push([
            { content: 'NOTA:', styles: { fontStyle: 'bold', fillColor: [225, 245, 250] } },
            { content: idr.issueNote, colSpan: 8, styles: { fillColor: [225, 245, 250], textColor: [0, 150, 180] } }
          ]);
        }
      });

      doc.autoTable({
        startY: tableAy,
        head: tableHead,
        body: tableBody,
        headStyles: { fillColor: [6, 182, 212], textColor: 255, fontStyle: 'bold', fontSize: 8, halign: 'left', valign: 'middle' },
        bodyStyles: { fontSize: 7.5, valign: 'top' },
        columnStyles: {
          0: { cellWidth: 18 },
          1: { cellWidth: 18 },
          2: { cellWidth: 22 },
          3: { cellWidth: 14, halign: 'center' },
          4: { cellWidth: 16, halign: 'center' },
          5: { cellWidth: 14, halign: 'center' },
          6: { cellWidth: 44, halign: 'left' },
          7: { cellWidth: 18, halign: 'center' },
          8: { cellWidth: 18, halign: 'center' }
        },
        theme: 'grid',
        margin: { left: 14, right: 14 },
        didParseCell: (data) => {
          if (data.section === 'body') {
            const rowIndex = data.rowIndex;
            // Verifica se è una riga di nota
            const isNoteRow = tableBody[rowIndex] && tableBody[rowIndex][0] && tableBody[rowIndex][0].colSpan;
            if (!isNoteRow) {
              const idr = idrantiList[rowIndex];
              if (idr && idr.hasIssue) {
                data.cell.styles.textColor = [210, 60, 60];
              }
              if (idr && new Date(idr.maintenanceDue) < new Date() && !idr.hasIssue) {
                data.cell.styles.textColor = [210, 60, 60];
              }
            }
          }
        }
      });
    }

    // ── Tabella Porte REI
    const porteREIList = extinguishers.filter(e => e.category === 'Porta REI');
    if (porteREIList.length > 0) {
      let tableAy = doc.lastAutoTable?.finalY ? doc.lastAutoTable.finalY + 10 : (doc.lastAutoTable?.finalY || 0) + 60;
      const pageH = doc.internal.pageSize.height;
      if (tableAy > pageH - 50) { doc.addPage(); tableAy = 20; }
      
      doc.setFontSize(10);
      doc.setTextColor(60, 60, 60);
      doc.setFont(undefined, 'bold');
      doc.text('Tabella Porte REI', 14, tableAy);
      tableAy += 7;

      const tableHead = [['Categoria', 'Tipo', 'Costruttore', 'Anno', 'Matricola', 'REI', 'N° Battenti', 'N°', 'Ubicazione', 'Scad. Mant.', 'Esito']];
      let tableBody = [];
      porteREIList.forEach(porta => {
        const esito = porta.hasIssue ? 'Problema' : (new Date(porta.maintenanceDue) < new Date() ? 'Scaduto' : 'Positivo');
        tableBody.push([
          porta.category || 'Porta REI',
          porta.portaReiSubtype || '',
          porta.costruttore || '',
          porta.anno || '',
          porta.matricola || '',
          porta.rei || '',
          porta.battenti || '',
          porta.number,
          porta.location || '',
          porta.maintenanceDue ? new Date(porta.maintenanceDue).toLocaleDateString('it-IT') : '',
          esito
        ]);
        // Se ha problema, aggiungi riga con nota
        if (porta.hasIssue && porta.issueNote) {
          tableBody.push([
            { content: 'NOTA:', styles: { fontStyle: 'bold', fillColor: [240, 230, 250] } },
            { content: porta.issueNote, colSpan: 10, styles: { fillColor: [240, 230, 250], textColor: [120, 80, 160] } }
          ]);
        }
      });

      doc.autoTable({
        startY: tableAy,
        head: tableHead,
        body: tableBody,
        headStyles: { fillColor: [34, 197, 94], textColor: 255, fontStyle: 'bold', fontSize: 8, halign: 'left', valign: 'middle' },
        bodyStyles: { fontSize: 7.5, valign: 'top' },
        columnStyles: {
          0: { cellWidth: 16 },
          1: { cellWidth: 16 },
          2: { cellWidth: 18 },
          3: { cellWidth: 12, halign: 'center' },
          4: { cellWidth: 14 },
          5: { cellWidth: 13, halign: 'center' },
          6: { cellWidth: 14, halign: 'center' },
          7: { cellWidth: 12, halign: 'center' },
          8: { cellWidth: 36, halign: 'left' },
          9: { cellWidth: 16, halign: 'center' },
          10: { cellWidth: 16, halign: 'center' }
        },
        theme: 'grid',
        margin: { left: 14, right: 14 },
        didParseCell: (data) => {
          if (data.section === 'body') {
            const rowIndex = data.rowIndex;
            // Verifica se è una riga di nota
            const isNoteRow = tableBody[rowIndex] && tableBody[rowIndex][0] && tableBody[rowIndex][0].colSpan;
            if (!isNoteRow) {
              const porta = porteREIList[rowIndex];
              if (porta && porta.hasIssue) {
                data.cell.styles.textColor = [210, 60, 60];
              }
              if (porta && new Date(porta.maintenanceDue) < new Date() && !porta.hasIssue) {
                data.cell.styles.textColor = [210, 60, 60];
              }
            }
          }
        }
      });
    }

    // ── Tabella MAPS
    const mapsList = extinguishers.filter(e => e.category === 'MAPS');
    if (mapsList.length > 0) {
      let tableAy = doc.lastAutoTable?.finalY ? doc.lastAutoTable.finalY + 10 : (doc.lastAutoTable?.finalY || 0) + 60;
      const pageH = doc.internal.pageSize.height;
      if (tableAy > pageH - 50) { doc.addPage(); tableAy = 20; }
      
      doc.setFontSize(10);
      doc.setTextColor(60, 60, 60);
      doc.setFont(undefined, 'bold');
      doc.text('Tabella MAPS', 14, tableAy);
      tableAy += 7;

      const tableHead = [['Categoria', 'Numero', 'Ubicazione', 'Scad. Mant.', 'Esito']];
      let tableBody = [];
      mapsList.forEach(maps => {
        const esito = maps.hasIssue ? 'Problema' : (new Date(maps.maintenanceDue) < new Date() ? 'Scaduto' : 'Positivo');
        tableBody.push([
          maps.category || 'MAPS',
          maps.number,
          maps.location || '',
          maps.maintenanceDue ? new Date(maps.maintenanceDue).toLocaleDateString('it-IT') : '',
          esito
        ]);
        // Se ha problema, aggiungi riga con nota
        if (maps.hasIssue && maps.issueNote) {
          tableBody.push([
            { content: 'NOTA:', styles: { fontStyle: 'bold', fillColor: [250, 235, 245] } },
            { content: maps.issueNote, colSpan: 4, styles: { fillColor: [250, 235, 245], textColor: [200, 60, 130] } }
          ]);
        }
      });

      doc.autoTable({
        startY: tableAy,
        head: tableHead,
        body: tableBody,
        headStyles: { fillColor: [236, 72, 153], textColor: 255, fontStyle: 'bold', fontSize: 8, halign: 'left', valign: 'middle' },
        bodyStyles: { fontSize: 7.5, valign: 'top' },
        columnStyles: {
          0: { cellWidth: 20 },
          1: { cellWidth: 18, halign: 'center' },
          2: { cellWidth: 80, halign: 'left' },
          3: { cellWidth: 18, halign: 'center' },
          4: { cellWidth: 18, halign: 'center' }
        },
        theme: 'grid',
        margin: { left: 14, right: 14 },
        didParseCell: (data) => {
          if (data.section === 'body') {
            const rowIndex = data.rowIndex;
            const isNoteRow = tableBody[rowIndex] && tableBody[rowIndex][0] && tableBody[rowIndex][0].colSpan;
            if (!isNoteRow) {
              const maps = mapsList[rowIndex];
              if (maps && maps.hasIssue) {
                data.cell.styles.textColor = [210, 60, 60];
              }
              if (maps && new Date(maps.maintenanceDue) < new Date() && !maps.hasIssue) {
                data.cell.styles.textColor = [210, 60, 60];
              }
            }
          }
        }
      });
    }

    // ── Tabella Motopompa VVF
    const motopompaList = extinguishers.filter(e => e.category === 'Motopompa VVF');
    if (motopompaList.length > 0) {
      let tableAy = doc.lastAutoTable?.finalY ? doc.lastAutoTable.finalY + 10 : (doc.lastAutoTable?.finalY || 0) + 60;
      const pageH = doc.internal.pageSize.height;
      if (tableAy > pageH - 50) { doc.addPage(); tableAy = 20; }
      
      doc.setFontSize(10);
      doc.setTextColor(60, 60, 60);
      doc.setFont(undefined, 'bold');
      doc.text('Tabella Motopompa VVF', 14, tableAy);
      tableAy += 7;

      const tableHead = [['Categoria', 'Numero', 'Ubicazione', 'Scad. Mant.', 'Esito']];
      let tableBody = [];
      motopompaList.forEach(moto => {
        const esito = moto.hasIssue ? 'Problema' : (new Date(moto.maintenanceDue) < new Date() ? 'Scaduto' : 'Positivo');
        tableBody.push([
          moto.category || 'Motopompa VVF',
          moto.number,
          moto.location || '',
          moto.maintenanceDue ? new Date(moto.maintenanceDue).toLocaleDateString('it-IT') : '',
          esito
        ]);
        // Se ha problema, aggiungi riga con nota
        if (moto.hasIssue && moto.issueNote) {
          tableBody.push([
            { content: 'NOTA:', styles: { fontStyle: 'bold', fillColor: [240, 235, 250] } },
            { content: moto.issueNote, colSpan: 4, styles: { fillColor: [240, 235, 250], textColor: [80, 40, 150] } }
          ]);
        }
      });

      doc.autoTable({
        startY: tableAy,
        head: tableHead,
        body: tableBody,
        headStyles: { fillColor: [109, 40, 217], textColor: 255, fontStyle: 'bold', fontSize: 8, halign: 'left', valign: 'middle' },
        bodyStyles: { fontSize: 7.5, valign: 'top' },
        columnStyles: {
          0: { cellWidth: 30 },
          1: { cellWidth: 18, halign: 'center' },
          2: { cellWidth: 70, halign: 'left' },
          3: { cellWidth: 18, halign: 'center' },
          4: { cellWidth: 18, halign: 'center' }
        },
        theme: 'grid',
        margin: { left: 14, right: 14 },
        didParseCell: (data) => {
          if (data.section === 'body') {
            const rowIndex = data.rowIndex;
            const isNoteRow = tableBody[rowIndex] && tableBody[rowIndex][0] && tableBody[rowIndex][0].colSpan;
            if (!isNoteRow) {
              const moto = motopompaList[rowIndex];
              if (moto && moto.hasIssue) {
                data.cell.styles.textColor = [210, 60, 60];
              }
              if (moto && new Date(moto.maintenanceDue) < new Date() && !moto.hasIssue) {
                data.cell.styles.textColor = [210, 60, 60];
              }
            }
          }
        }
      });
    }

    // ── Note generali
    let curY = doc.lastAutoTable.finalY + 8;
    if (reportNotes) {
      doc.setFontSize(9);
      doc.setTextColor(60, 60, 60);
      doc.setFont(undefined, 'bold');
      doc.text('Note:', 14, curY);
      doc.setFont(undefined, 'normal');
      doc.setTextColor(80, 80, 80);
      const noteLines = doc.splitTextToSize(reportNotes, 182);
      doc.text(noteLines, 14, curY + 5);
      curY += 6 + noteLines.length * 5;
    }

    // ── Footer
    const pageH = doc.internal.pageSize.height;


    // ── Problemi rilevati
    let opY = doc.lastAutoTable.finalY + 8;
    const issueDevices = extinguishers.filter(e => e.hasIssue);
    if (issueDevices.length > 0) {
      const issueBlockH = 9 + issueDevices.reduce((acc, e) => acc + (e.issueNote ? Math.ceil(doc.splitTextToSize(e.issueNote, 178).length * 4.5) + 10 : 8), 0);
      if (opY + issueBlockH > pageH - 20) { doc.addPage(); opY = 20; }
      doc.setFontSize(10);
      doc.setTextColor(180, 110, 0);
      doc.setFont(undefined, 'bold');
      doc.text('Problemi Rilevati', 14, opY);
      opY += 6;
      issueDevices.forEach(ext => {
        const cat = EQUIPMENT_CATEGORIES.find(c => c.id === (ext.category || 'Estintore')) || EQUIPMENT_CATEGORIES[0];
        const devLabel = `${cat.label}${ext.category === 'Idrante' && ext.hydrantSubtype ? ' ' + ext.hydrantSubtype : ''} N° ${ext.number} — ${ext.location}`;
        doc.setFontSize(8.5);
        doc.setTextColor(50, 50, 50);
        doc.setFont(undefined, 'bold');
        doc.text(devLabel, 14, opY);
        opY += 4.5;
        if (ext.issueNote) {
          doc.setFont(undefined, 'italic');
          doc.setTextColor(100, 100, 100);
          const noteLines = doc.splitTextToSize(ext.issueNote, 178);
          doc.text(noteLines, 18, opY);
          opY += noteLines.length * 4.5 + 3;
        } else {
          opY += 3;
        }
      });
      doc.setDrawColor(220, 220, 220);
      doc.setLineWidth(0.3);
      doc.line(14, opY, 196, opY);
      opY += 6;
    }

    // ── Operazioni effettuate (2 colonne per compattezza, solo le selezionate)
    const checkedOps = REPORT_OPS.filter(op => reportOps.find(o => o.id === op.id)?.checked);

    // Calcola spazio necessario: titolo(7) + righe ops(ceil(n/2)*5) + sep(5) + firme(28) + disclaimer(8) + margine footer(14)
    const opsBlockH = (checkedOps.length > 0 ? 7 + Math.ceil(checkedOps.length / 2) * 5 : 0) + 5 + 28 + 8 + 14;
    if (opY + opsBlockH > pageH) { doc.addPage(); opY = 20; }

    const opsColW = 91; // larghezza colonna operazioni (2 col su 182mm)
    const rowH = 5;    // altezza riga
    const bSz  = 3.6;  // dimensione checkbox

    if (checkedOps.length > 0) {
      doc.setFontSize(10);
      doc.setTextColor(40, 40, 40);
      doc.setFont(undefined, 'bold');
      doc.text(reportOpType === 'ordinaria' ? 'Operazioni ordinarie:' : 'Operazioni straordinarie:', 14, opY);
      opY += 7;

      checkedOps.forEach((op, idx) => {
        const col = idx % 2;
        const row = Math.floor(idx / 2);
        const x   = 14 + col * opsColW;
        const y   = opY + row * rowH;
        const opState  = reportOps.find(o => o.id === op.id);

        // ── Disegna checkbox manualmente (sempre selezionato)
        doc.setFillColor(249, 115, 22);
        doc.setDrawColor(249, 115, 22);
        doc.setLineWidth(0.1);
        doc.rect(x, y - bSz + 0.4, bSz, bSz, 'FD');
        // Checkmark bianco con linee
        doc.setDrawColor(255, 255, 255);
        doc.setLineWidth(0.75);
        doc.line(x + 0.55, y - 1.1, x + 1.45, y - 0.15);  // gamba sinistra
        doc.line(x + 1.45, y - 0.15, x + 3.15, y - 2.7);  // gamba destra

        // ── Etichetta
        doc.setFontSize(8);
        doc.setFont(undefined, 'normal');
        doc.setTextColor(25, 25, 25);
        let lineLabel = adaptLabel(op.label);
        if (op.hasField) {
          const fieldVal = opState?.fieldValue?.trim();
          lineLabel += ' ' + (fieldVal || op.fieldPlaceholder);
        }
        doc.text(lineLabel, x + bSz + 2, y, { maxWidth: opsColW - bSz - 4 });
      });

      opY += Math.ceil(checkedOps.length / 2) * rowH + 5;
    }

    // ── Separatore firme
    doc.setDrawColor(210, 210, 210);
    doc.setLineWidth(0.3);
    doc.line(14, opY, 196, opY);
    opY += 7;

    const sigW  = 75;
    const sig1X = 14;
    const sig2X = 14 + sigW + (182 - sigW * 2);

    doc.setFontSize(8.5);
    doc.setTextColor(80, 80, 80);
    doc.setFont(undefined, 'bold');
    doc.text('Firma del Tecnico', sig1X, opY);
    doc.text('Firma per Accettazione', sig2X, opY);
    opY += 16;
    doc.setDrawColor(60, 60, 60);
    doc.setLineWidth(0.4);
    doc.line(sig1X, opY, sig1X + sigW, opY);
    doc.line(sig2X, opY, sig2X + sigW, opY);

    const techLabel = reportTechnician.trim();
    doc.setFontSize(7.5);
    doc.setTextColor(130, 130, 130);
    doc.setFont(undefined, 'normal');
    if (techLabel) doc.text(techLabel, sig1X, opY + 4);
    opY += 10;

    // ── Nota finale
    doc.setFontSize(7.5);
    doc.setTextColor(120, 120, 120);
    doc.setFont(undefined, 'italic');
    const disclaimerText = 'Il cliente dichiara che i lavori sopra descritti sono stati effettuati ed accetta le integrazioni indicate nelle note.';
    doc.text(doc.splitTextToSize(disclaimerText, 182), 14, opY);

    // ── Pagina planimetria
    if (reportFloorPlan) {
      doc.addPage();
      const fpW = doc.internal.pageSize.width;
      const fpH = doc.internal.pageSize.height;

      const hexToRgb = (hex) => [parseInt(hex.slice(1,3),16), parseInt(hex.slice(3,5),16), parseInt(hex.slice(5,7),16)];

      // Titolo
      doc.setFontSize(11);
      doc.setTextColor(40, 40, 40);
      doc.setFont(undefined, 'bold');
      doc.text('Planimetria', 14, 18);
      doc.setDrawColor(255, 95, 31);
      doc.setLineWidth(0.4);
      doc.line(14, 21, fpW - 14, 21);

      // Legenda inline sotto la linea
      const usedCats = EQUIPMENT_CATEGORIES.filter(c => extinguishers.some(e => (e.category || 'Estintore') === c.id));
      const legendItems = [
        ...usedCats.map(c => ({ label: c.label, col: hexToRgb(c.color) })),
        { label: 'Scaduto', col: [239, 68, 68] },
        { label: 'Problema', col: [245, 158, 11] },
      ];
      doc.setFontSize(6.5);
      doc.setFont(undefined, 'normal');
      let lx = 14;
      const ly = 26.5;
      const dotR = 1.3;
      legendItems.forEach(item => {
        doc.setFillColor(...item.col);
        doc.setDrawColor(...item.col);
        doc.circle(lx + dotR, ly, dotR, 'F');
        doc.setTextColor(80, 80, 80);
        doc.text(item.label, lx + dotR * 2 + 1, ly + 0.9);
        lx += dotR * 2 + 1 + doc.getTextWidth(item.label) + 3.5;
      });

      const maxImgW = fpW - 28;
      const imgY = 32;
      const maxImgH = fpH - imgY - 10;

      const { w: natW, h: natH } = await new Promise(res => {
        const img = new Image();
        img.onload = () => res({ w: img.naturalWidth, h: img.naturalHeight });
        img.onerror = () => res({ w: 16, h: 9 });
        img.src = reportFloorPlan;
      });

      const isLandscape = natW > natH;
      let finalImgData = reportFloorPlan;
      let finalW = natW;
      let finalH = natH;

      if (isLandscape) {
        finalImgData = await new Promise(res => {
          const img = new Image();
          img.onload = () => {
            const canvas = document.createElement('canvas');
            canvas.width = natH;
            canvas.height = natW;
            const ctx = canvas.getContext('2d');
            ctx.translate(natH / 2, natW / 2);
            ctx.rotate(Math.PI / 2);
            ctx.drawImage(img, -natW / 2, -natH / 2);
            res(canvas.toDataURL('image/jpeg', 0.92));
          };
          img.onerror = () => res(reportFloorPlan);
          img.src = reportFloorPlan;
        });
        finalW = natH;
        finalH = natW;
      }

      const ratio = finalW / finalH;
      let imgW = maxImgW;
      let imgH = imgW / ratio;
      if (imgH > maxImgH) { imgH = maxImgH; imgW = imgH * ratio; }
      const imgX = 14 + (maxImgW - imgW) / 2;

      try { doc.addImage(finalImgData, 'JPEG', imgX, imgY, imgW, imgH); } catch(e) {}

      // ── Markers dispositivi (colori categoria + stato)
      const now = new Date();
      extinguishers.forEach(ext => {
        if (!ext.position) return;
        let px = parseFloat(ext.position.x) / 100;
        let py = parseFloat(ext.position.y) / 100;
        if (isLandscape) { const tmp = px; px = 1 - py; py = tmp; }
        const mx = imgX + px * imgW;
        const my = imgY + py * imgH;
        const r = 2.5;
        let col;
        if (ext.hasIssue) col = [245, 158, 11];
        else if (new Date(ext.maintenanceDue) < now) col = [239, 68, 68];
        else { const cat = EQUIPMENT_CATEGORIES.find(c => c.id === (ext.category || 'Estintore')) || EQUIPMENT_CATEGORIES[0]; col = hexToRgb(cat.color); }
        doc.setFillColor(...col);
        doc.setDrawColor(255, 255, 255);
        doc.setLineWidth(0.4);
        doc.circle(mx, my, r, 'FD');
        doc.setFontSize(4.5);
        doc.setTextColor(255, 255, 255);
        doc.setFont(undefined, 'bold');
        doc.text(String(ext.number), mx, my + 1.4, { align: 'center' });
      });
    }

    // ── Footer su ogni pagina
    const totalPages = doc.internal.getNumberOfPages();
    for (let i = 1; i <= totalPages; i++) {
      doc.setPage(i);
      doc.setFontSize(8);
      doc.setTextColor(170, 170, 170);
      doc.setFont(undefined, 'normal');
      doc.text('FireCheck — Sistema Gestione Presidi Antincendio', 14, pageH - 6);
      doc.text(`Pag. ${i}/${totalPages}`, 196, pageH - 6, { align: 'right' });
    }

    doc.save(`rapporto_${todayStr}.pdf`);
    setShowReportModal(false);
    setReportNotes('');
    setReportOps(defaultOps());
    showToast('Rapporto PDF generato', 'success');
  };

  return (
    <div className="card">
      <div className="flex-between gap-md" style={{ marginBottom: '1rem' }}>
        <div className="card-title" style={{ marginBottom: 0 }}><span className="ct-icon">☰</span> Storico Controlli</div>
        <div className="flex gap-sm">
          <button className="btn btn-primary btn-sm" onClick={() => { setReportNotes(''); setReportTechnician(''); setReportCompany({ azienda: '', indirizzo: '', riferimento: '' }); setReportOps(defaultOps()); setReportOpType('ordinaria'); setShowReportModal(true); }}>📄 Genera Rapportino</button>
          {records.length > 0 && <button className="btn btn-success btn-sm" onClick={downloadCSV}>⬇ CSV</button>}
        </div>
      </div>
      {usedNumbers.length > 0 && (
        <div className="history-filter">
          <div className={`filter-chip ${filterExt === 'all' ? 'active' : ''}`} onClick={() => setFilterExt('all')}>Tutti ({records.length})</div>
          {usedNumbers.map(n => (
            <div key={n} className={`filter-chip ${filterExt === n ? 'active' : ''}`} onClick={() => setFilterExt(n)}>
              {n} ({records.filter(r => r.extNumber === n).length})
            </div>
          ))}
        </div>
      )}
      {filtered.length === 0
        ? <div className="empty-state"><div className="empty-icon">📋</div><p>Nessun controllo registrato per questo progetto.</p></div>
        : (
          <table>
            <thead>
              <tr>
                <th>N\u00b0</th>
                <th>Tipo</th>
                <th>Ubicazione</th>
                <th>Data e Ora</th>
                <th>Operatore</th>
                <th>Esito</th>
              </tr>
            </thead>
            <tbody>
              {filtered.map(r => {
                const positive = isExtPositive(r.extNumber);
                return (
                  <tr key={r.id}>
                    <td className="td-mono">{r.extNumber}</td>
                    <td className="text-sm">{getItemCategory(r.extNumber)}</td>
                    <td>{getExtLocation(r.extNumber)}</td>
                    <td className="td-mono">{new Date(r.timestamp).toLocaleString('it-IT')}</td>
                    <td className="text-muted text-sm">{r.operator || '—'}</td>
                    <td><span className={`badge ${positive ? 'badge-ok' : 'badge-issue'}`}>{positive ? '✓ Positivo' : '⚠ Negativo'}</span></td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        )
      }

      {/* REPORT MODAL */}
      {showReportModal && (
        <div className="modal" onClick={() => setShowReportModal(false)}>
          <div className="modal-box" onClick={e => e.stopPropagation()}>
            <div className="modal-title">📄 Genera Rapportino PDF</div>
            <hr className="modal-divider" />
            <div className="section-label" style={{ marginBottom: '0.5rem' }}>Tipo Manutenzione</div>
            <div className="sort-group" style={{ display: 'inline-flex', marginBottom: '1.25rem' }}>
              <button className={`sort-btn ${reportOpType === 'ordinaria' ? 'active' : ''}`} onClick={() => setReportOpType('ordinaria')}>Ordinaria</button>
              <button className={`sort-btn ${reportOpType === 'straordinaria' ? 'active' : ''}`} onClick={() => setReportOpType('straordinaria')}>Straordinaria</button>
            </div>
            <div className="section-label" style={{ marginBottom: '0.5rem' }}>Dati Azienda</div>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0 0.75rem' }}>
              <div>
                <label className="label">Azienda</label>
                <input className="input" placeholder="Nome azienda" value={reportCompany.azienda} onChange={e => setReportCompany({ ...reportCompany, azienda: e.target.value })} />
              </div>
              <div>
                <label className="label">Riferimento interno</label>
                <input className="input" placeholder="es. Mario Rossi" value={reportCompany.riferimento} onChange={e => setReportCompany({ ...reportCompany, riferimento: e.target.value })} />
              </div>
            </div>
            <label className="label">Sede</label>
            <input className="input" placeholder="Indirizzo / sede" value={reportCompany.indirizzo} onChange={e => setReportCompany({ ...reportCompany, indirizzo: e.target.value })} />
            <label className="label">Nome e Cognome Tecnico</label>
            <input className="input" placeholder="es. Mario Rossi" value={reportTechnician} onChange={e => setReportTechnician(e.target.value)} />
            {todayRecords.length === 0 ? (
              <div style={{ textAlign: 'center', padding: '1rem 0', color: 'var(--text-muted)', fontSize: '0.875rem' }}>
                <div style={{ fontSize: '2rem', marginBottom: '0.5rem' }}>📋</div>
                <p>Nessun controllo registrato oggi.<br/>Il rapportino include solo i controlli della data odierna.</p>
              </div>
            ) : (
              <div style={{ marginBottom: '1rem' }}>
                {EQUIPMENT_CATEGORIES.filter(c => todayRecords.some(r => getItemCategory(r.extNumber) === c.id)).map(c => {
                  const recs = todayRecords.filter(r => getItemCategory(r.extNumber) === c.id);
                  const pos = recs.filter(r => isExtPositive(r.extNumber)).length;
                  const neg = recs.length - pos;
                  return (
                    <div key={c.id} style={{ display: 'grid', gridTemplateColumns: '1fr repeat(3,52px)', gap: '0.4rem', marginBottom: '0.4rem', alignItems: 'center', background: 'var(--surface-2)', border: '1px solid var(--border)', borderLeft: `3px solid ${c.color}`, borderRadius: 'var(--radius)', padding: '0.5rem 0.75rem' }}>
                      <div style={{ fontSize: '0.85rem', fontWeight: 500 }}>{c.icon} {c.label}</div>
                      <div style={{ textAlign: 'center' }}><div style={{ fontFamily: 'var(--font-mono)', fontWeight: 700, color: 'var(--blue)', fontSize: '1.1rem' }}>{recs.length}</div><div style={{ fontSize: '0.62rem', color: 'var(--text-muted)', textTransform: 'uppercase' }}>tot</div></div>
                      <div style={{ textAlign: 'center' }}><div style={{ fontFamily: 'var(--font-mono)', fontWeight: 700, color: 'var(--green)', fontSize: '1.1rem' }}>{pos}</div><div style={{ fontSize: '0.62rem', color: 'var(--text-muted)', textTransform: 'uppercase' }}>pos</div></div>
                      <div style={{ textAlign: 'center' }}><div style={{ fontFamily: 'var(--font-mono)', fontWeight: 700, color: neg > 0 ? 'var(--red)' : 'var(--text-muted)', fontSize: '1.1rem' }}>{neg}</div><div style={{ fontSize: '0.62rem', color: 'var(--text-muted)', textTransform: 'uppercase' }}>neg</div></div>
                    </div>
                  );
                })}
              </div>
            )}
            <label className="label">Note (opzionale)</label>
            <textarea
              className="input"
              rows={3}
              style={{ resize: 'vertical', fontFamily: 'var(--font-body)', height: 'auto' }}
              placeholder="Inserisci eventuali note da includere nel rapportino..."
              value={reportNotes}
              onChange={e => setReportNotes(e.target.value)}
            />
            <div className="section-label" style={{ margin: '0.25rem 0 0.5rem' }}>Operazioni {reportOpType === 'ordinaria' ? 'Ordinarie' : 'Straordinarie'}</div>
            {REPORT_OPS.map(op => {
              const opState = reportOps.find(o => o.id === op.id);
              return (
                <div key={op.id} style={{ marginBottom: '0.45rem' }}>
                  <label style={{ display: 'flex', alignItems: 'center', gap: '0.6rem', cursor: 'pointer', fontSize: '0.875rem', color: opState?.checked ? 'var(--text)' : 'var(--text-muted)' }}>
                    <input
                      type="checkbox"
                      checked={opState?.checked || false}
                      onChange={e => setReportOps(reportOps.map(o => o.id === op.id ? { ...o, checked: e.target.checked } : o))}
                      style={{ width: 15, height: 15, accentColor: 'var(--orange)', flexShrink: 0 }}
                    />
                    {adaptLabel(op.label)}
                    {op.hasField && opState?.checked && (
                      <input
                        className="input"
                        style={{ marginBottom: 0, width: 90, padding: '0.3rem 0.5rem', fontSize: '0.8rem' }}
                        placeholder={op.fieldPlaceholder}
                        value={opState?.fieldValue || ''}
                        onClick={e => e.stopPropagation()}
                        onChange={e => setReportOps(reportOps.map(o => o.id === op.id ? { ...o, fieldValue: e.target.value } : o))}
                      />
                    )}
                  </label>
                </div>
              );
            })}
            <div className="flex gap-sm" style={{ marginTop: '0.25rem' }}>
              <button className="btn btn-primary" style={{ flex: 1, justifyContent: 'center' }} onClick={generateReport} disabled={todayRecords.length === 0}>
                📄 Genera PDF
              </button>
              <button className="btn btn-ghost" style={{ flex: 1, justifyContent: 'center' }} onClick={() => setShowReportModal(false)}>Annulla</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

// ─── ADMIN ────────────────────────────────────────────────────────────────────
function Admin({ activeProjectId, showToast }) {
  const [extinguishers, setExtinguishers] = useState([]);
  const [editExt, setEditExt] = useState(null);
  const [uploading, setUploading] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [sortBy, setSortBy] = useState('number');
  const fileInputRef = useRef(null);

  useEffect(() => { loadData(); }, [activeProjectId]);

  const loadData = () => {
    let data = getProjectData(activeProjectId, 'extinguishers') || [];
    data = data.map(e => migrateExt({ ...e, hasIssue: e.hasIssue ?? false }));
    setExtinguishers(data);
  };
  const saveExtinguishers = (upd) => { saveProjectData(activeProjectId, 'extinguishers', upd); loadData(); };
  const saveFloorPlan = (url) => saveProjectData(activeProjectId, 'floorplan', url);

  const handleDelete = (id) => {
    if (!confirm('Eliminare questo elemento?')) return;
    saveExtinguishers(extinguishers.filter(e => e.id !== id));
    showToast('Elemento eliminato', 'warning');
  };
  const handleSaveExt = () => {
    saveExtinguishers(extinguishers.map(e => e.id === editExt.id ? editExt : e));
    setEditExt(null);
    showToast('Modifiche salvate', 'success');
  };

  const handleExportBackup = () => {
    try {
      const bd = {};
      FIRECHECK_STORAGE_KEYS.forEach(k => { const d = localStorage.getItem(k); if (d) bd[k] = d; });
      const pd = localStorage.getItem('firecheck_projects_data');
      if (pd) bd['firecheck_projects_data'] = pd;
      const a = document.createElement('a');
      a.href = URL.createObjectURL(new Blob([JSON.stringify(bd, null, 2)], { type: 'application/json' }));
      a.download = `firecheck_backup_${new Date().toISOString().split('T')[0]}.json`;
      a.click();
      showToast('Backup esportato', 'success');
    } catch (e) { showToast('Errore backup: ' + e.message, 'error'); }
  };

  const handleImportBackup = (e) => {
    const file = e.target.files[0];
    if (!file) return;
    if (!confirm('Sovrascrivere TUTTI i dati attuali con il backup? L\'operazione è irreversibile.')) { e.target.value = ''; return; }
    setUploading(true);
    const reader = new FileReader();
    reader.onload = (ev) => {
      try {
        const data = JSON.parse(ev.target.result);
        const keys = [...FIRECHECK_STORAGE_KEYS, 'firecheck_projects_data'];
        let count = 0;
        for (const k in data) { if (keys.includes(k)) { localStorage.setItem(k, data[k]); count++; } }
        if (!count) throw new Error('Nessun dato valido trovato');
        setUploading(false);
        showToast(`Dati ripristinati (${count} voci)`, 'success');
        e.target.value = '';
        setTimeout(() => window.location.reload(), 1500);
      } catch (err) {
        setUploading(false);
        showToast('Errore ripristino: ' + err.message, 'error');
        e.target.value = '';
      }
    };
    reader.onerror = () => { setUploading(false); showToast('Errore lettura file', 'error'); e.target.value = ''; };
    reader.readAsText(file);
  };

  const compressImage = (file, mw = 1920, mh = 1080, q = 0.85) => new Promise((res, rej) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        let w = img.width, h = img.height;
        if (w > h) { if (w > mw) { h = Math.round(h * mw / w); w = mw; } }
        else { if (h > mh) { w = Math.round(w * mh / h); h = mh; } }
        const c = document.createElement('canvas');
        c.width = w; c.height = h;
        c.getContext('2d').drawImage(img, 0, 0, w, h);
        const out = c.toDataURL('image/jpeg', q);
        if ((out.length * 0.75) / (1024 * 1024) > 4 && q > 0.5) compressImage(file, mw * 0.8, mh * 0.8, q - 0.2).then(res).catch(rej);
        else res(out);
      };
      img.onerror = () => rej(new Error('Errore immagine'));
      img.src = e.target.result;
    };
    reader.onerror = () => rej(new Error('Errore lettura'));
    reader.readAsDataURL(file);
  });

  const handleFileUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    if (!file.type.startsWith('image/')) { showToast('Carica un file immagine', 'warning'); return; }
    if (file.size > 20 * 1024 * 1024) { showToast('File troppo grande (max 20MB)', 'error'); return; }
    setUploading(true);
    try {
      const compressed = await compressImage(file);
      saveFloorPlan(compressed);
      showToast('Planimetria caricata', 'success');
    } catch (err) { showToast('Errore caricamento: ' + err.message, 'error'); }
    finally { setUploading(false); e.target.value = ''; }
  };

  const filtered = extinguishers
    .filter(e => [e.number, e.location, e.type, e.category || 'Estintore', e.hydrantSubtype || '', e.matricola || '', e.costruttore || ''].some(f => (f || '').toLowerCase().includes(searchTerm.toLowerCase())))
    .sort((a, b) => sortBy === 'number' ? parseInt(a.number) - parseInt(b.number) : a.location.localeCompare(b.location));

  const getStatus = (ext) => {
    if (ext.hasIssue) return { cls: 'has-issue', badge: <span className="badge badge-issue">⚠ Problema</span> };
    if (new Date(ext.maintenanceDue) < new Date()) return { cls: 'is-expired', badge: <span className="badge badge-expired">Scaduto</span> };
    return { cls: 'is-ok', badge: <span className="badge badge-ok">OK</span> };
  };

  return (
    <div>
      {/* PLANIMETRIA */}
      <div className="card">
        <div className="card-title"><span className="ct-icon">📄</span> Planimetria</div>
        <div className="file-upload" onClick={() => !uploading && fileInputRef.current?.click()} style={{ opacity: uploading ? 0.6 : 1, cursor: uploading ? 'wait' : 'pointer' }}>
          {uploading
            ? <><div className="file-upload-title">⏳ Caricamento in corso…</div><div className="text-sm">Compressione e ottimizzazione</div></>
            : <><div className="file-upload-title">📤 Carica nuova planimetria</div><div className="text-sm">JPG, PNG, SVG — max 20MB</div></>
          }
          <input ref={fileInputRef} type="file" accept="image/*" onChange={handleFileUpload} disabled={uploading} />
        </div>
      </div>

      {/* BACKUP */}
      <div className="card">
        <div className="card-title"><span className="ct-icon">💾</span> Backup e Ripristino</div>
        <div className="flex gap-sm" style={{ flexWrap: 'wrap' }}>
          <button className="btn btn-primary" style={{ flex: 1 }} onClick={handleExportBackup}>⬇ Esporta Backup (JSON)</button>
          <div className="file-upload" onClick={() => !uploading && document.getElementById('import-file-input').click()} style={{ flex: 1, padding: '0.55rem 1.1rem', margin: 0, cursor: uploading ? 'wait' : 'pointer', opacity: uploading ? 0.6 : 1 }}>
            {uploading ? '⏳ Caricamento…' : '⬆ Importa Backup (JSON)'}
            <input id="import-file-input" type="file" accept="application/json" onChange={handleImportBackup} disabled={uploading} />
          </div>
        </div>
        <p className="text-sm text-muted" style={{ marginTop: '0.75rem' }}>Il backup include tutti i progetti, estintori e storico. Dopo il ripristino la pagina si ricaricherà.</p>
      </div>

      {/* ESTINTORI */}
      <div className="card">
        <div className="flex-between gap-md" style={{ marginBottom: '1rem' }}>
          <div className="card-title" style={{ marginBottom: 0 }}><span className="ct-icon">🛡️</span> Dispositivi Antincendio ({extinguishers.length})</div>
        </div>
        <div className="toolbar">
          <div className="search-wrap">
            <span className="search-icon">⌕</span>
            <input className="input" style={{ marginBottom: 0 }} placeholder="Cerca per numero, ubicazione, categoria…" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
          </div>
          <div className="sort-group">
            <div className={`sort-btn ${sortBy === 'number' ? 'active' : ''}`} onClick={() => setSortBy('number')}># Numero</div>
            <div className={`sort-btn ${sortBy === 'location' ? 'active' : ''}`} onClick={() => setSortBy('location')}>⌖ Ubicazione</div>
          </div>
        </div>
        {filtered.length === 0
          ? <div className="empty-state"><div className="empty-icon">🔍</div><p>Nessun dispositivo trovato.</p></div>
          : filtered.map(ext => {
            const { cls, badge } = getStatus(ext);
            return (
              <div key={ext.id} className={`ext-row ${cls}`}>
                <div className="ext-number">{ext.number}</div>
                <div className="ext-info">
                  <div className="ext-location">{ext.location}</div>
                  <div className="ext-meta">{ext.category || 'Estintore'}{ext.category === 'Idrante' && ext.hydrantSubtype ? ` ${ext.hydrantSubtype}` : ''}{ext.category === 'Porta REI' && ext.portaReiSubtype && ext.portaReiSubtype !== 'Porta REI' ? ` → ${ext.portaReiSubtype}` : ''}{ext.category === 'Porta REI' && ext.rei ? ` · ${ext.rei}` : ''}{ext.category === 'Porta REI' && ext.matricola ? ` · ${ext.matricola}` : ''}{(ext.category === 'Estintore' || !ext.category) ? ` · ${ext.type}` : ''}{ext.matricola ? ` · ${ext.matricola}` : ''}{ext.category === 'Idrante' && ext.lunghezza ? ` · ${ext.lunghezza} m` : ''} · Scad. {new Date(ext.maintenanceDue).toLocaleDateString('it-IT')}{ext.scadenzaRevisione ? ` · Rev. ${ext.scadenzaRevisione}` : ''}{ext.scadenzaCollaudo ? ` · Coll. ${ext.scadenzaCollaudo}` : ''}</div>
                </div>
                {badge}
                <div className="ext-actions">
                  <button className="btn btn-primary btn-sm" onClick={() => setEditExt({ ...ext })}>✏</button>
                  <button className="btn btn-danger btn-sm" onClick={() => handleDelete(ext.id)}>🗑</button>
                </div>
              </div>
            );
          })
        }
      </div>

      <ExtEditModal editExt={editExt} setEditExt={setEditExt} onSave={handleSaveExt} onClose={() => setEditExt(null)} />
    </div>
  );
}

ReactDOM.createRoot(document.getElementById('root')).render(<App />);

// Rimuove lo splash di caricamento (definito in header.html) dopo il primo render
requestAnimationFrame(() => {
  const loader = document.getElementById('app-loader');
  if (loader) {
    loader.style.opacity = '0';
    setTimeout(() => loader.remove(), 300);
  }
});
